// A room of Right Door, Wrong Exit built in Blender (docs/BLENDER_AREAS.md, section 7): world/rdwe_<room>.glb for the art, with its light
// baked (each material names its lightmap in its glTF extras, on the second UV set, as everywhere else in the world: docs/BLENDER.md, R1),
// and world/rdwe_<room>.json for the rest: colliders (3D boxes: these rooms have stairs and landings), door leaves, and the room's links.
// The room graph (which door leads where) is games/rdwe/blender_rooms.js, generated by tools/blender/rdwe_links.py.
//
// buildRoom(id) returns what walk.js's start() runs, like a scene module's build(), plus:
//   world               the 3D boxes for controls.setWorld (the doors' boxes among them, `off` while open)
//   links               one aimless "use" target per way out: E / F / Enter (or X on a pad) near a link's `at` goes through
//   arrival(via)        where a walker coming in by door `via` stands and looks ({x, y, z, yaw}); opens that door behind them unless it is one-way
//   leave(door, ctx)    opens the door and sets the exit path through it (walk.js then plays the exit and resolves 'reached')
//   next(door)          where leaving by `door` goes: {room, via} | {leave: door} (the game ends) | null; door null is the story's way on (SPINE)
// No lights are added: all of the room's light is in the bake. A material without a bake keeps its glow if it has one and is drawn unlit
// otherwise. The walker is drawn at its own size here (scale 1): these rooms are built to the walker, not shrunk to it.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';
import { ROOMS, SPINE } from './blender_rooms.js';

const ROOT = new URL('../../', import.meta.url);           // the site root: the json names its lightmaps from there (world/lightmaps/...)
const at = (p) => new URL(p, ROOT).href;
let loader = null;
function gltf() {
  if (loader) return loader;
  const draco = new DRACOLoader();
  draco.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');
  loader = new GLTFLoader();
  loader.setDRACOLoader(draco);
  return loader;
}

export const hasRoom = (id) => Object.hasOwn(ROOMS, id);
export const roomIds = () => Object.keys(ROOMS);
export { ROOMS, SPINE };

const qy = (a) => new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), a);
const yawOf = (face) => Math.atan2(-face[0], -face[1]);
const LINK_REACH = 1.5, LINK_RISE = 1.3;                   // how near (on the floor, and in height) a link's `at` the walker must be

// The prompt for a way out: what you do there
const VERB = { sleep: 'CLOSE YOUR EYES', grate: 'STEP ON THE GRATE', glow: 'WALK INTO THE GLOW', hatch: 'GO THROUGH THE HATCH', drum: 'CLIMB INTO THE DRUM',
  machine: 'OPEN THE MACHINE', painted: 'OPEN THE PAINTED DOOR', reflection: 'GO THROUGH', bounce: 'CRAWL INTO THE VENT', well: 'GO DOWN THE WELL' };
const labelOf = (door, e) => (e.out === 'leave' ? 'LEAVE' : VERB[door] || (/^lift/.test(door) ? 'TAKE THE LIFT' : e.leaf ? 'OPEN THE DOOR' : 'GO ON'));

// The baked light: a material with a lightmap becomes an unlit one showing its texture times the light (the page's applyLightmaps, index.html).
// Returns {baked: [materials], textures: [the lightmaps]}; a material whose bake cannot be loaded is left as the file had it.
async function applyLightmaps(root) {
  const tl = new THREE.TextureLoader(), maps = new Map(), done = new Map(), out = { baked: [], textures: [], plain: [] };
  const image = (u) => maps.get(u) || maps.set(u, new Promise((res) => tl.load(at(u), (t) => { t.flipY = false; t.colorSpace = THREE.SRGBColorSpace; t.channel = 1; out.textures.push(t); res(t); }, undefined, () => res(null)))).get(u);
  const jobs = [];
  root.traverse((o) => {
    if (!o.isMesh || Array.isArray(o.material)) return;
    const src = o.material, u = src.userData || {};
    if (u.lightmap && o.geometry.attributes.uv1) {
      jobs.push((async () => {
        const tex = await image(u.lightmap), night = u.lightmap_night ? await image(u.lightmap_night) : null;
        if (!tex) return;
        let m = done.get(src);
        if (!m) {
          m = new THREE.MeshBasicMaterial({ name: src.name, color: src.color, map: src.map, transparent: src.transparent, opacity: src.opacity, alphaTest: src.alphaTest,
            side: src.side, depthWrite: src.depthWrite, vertexColors: src.vertexColors, lightMap: tex, lightMapIntensity: u.lightmap_intensity || 1 });
          m.userData = { ...u, baked: true, sets: { day: [tex, u.lightmap_intensity || 1], night: night ? [night, u.lightmap_night_intensity || 1] : null } };
          done.set(src, m); out.baked.push(m);
          for (const k of ['normalMap', 'roughnessMap', 'metalnessMap', 'aoMap', 'emissiveMap']) if (src[k] && src[k] !== src.map) src[k].dispose();
          src.dispose();
        }
        o.material = m;
      })());
      return;
    }
    // no bake: a glowing material keeps its glow (there is no light to show the rest of it); anything else is drawn unlit, a little dim
    const glows = src.emissive && (src.emissive.r + src.emissive.g + src.emissive.b) > 0 && (src.emissiveIntensity ?? 1) > 0;
    if (glows) { src.envMapIntensity = 0; src.userData.emit0 = src.emissiveIntensity; return; }
    let m = done.get(src);
    if (!m) {
      m = new THREE.MeshBasicMaterial({ name: src.name, color: (src.color || new THREE.Color(0x808080)).clone().multiplyScalar(0.55), map: src.map || null,
        transparent: src.transparent, opacity: src.opacity, alphaTest: src.alphaTest, side: src.side, depthWrite: src.depthWrite });
      m.userData = { ...u, plain: true };
      done.set(src, m); out.plain.push(m);
    }
    o.material = m;
  });
  await Promise.all(jobs);
  return out;
}

function loadGlb(u) { return new Promise((res, rej) => gltf().load(at(u), res, undefined, rej)); }

export async function buildRoom(id, { meta: codeMeta = null } = {}) {
  const R = ROOMS[id];
  if (!R) throw new Error(`rdwe: no Blender room "${id}"`);
  const [gl, doc] = await Promise.all([loadGlb(`world/${R.scene}.glb`), fetch(at(`world/${R.scene}.json`)).then((r) => { if (!r.ok) throw new Error(`world/${R.scene}.json: ${r.status}`); return r.json(); })]);
  const group = gl.scene;
  group.name = R.scene;
  const bake = await applyLightmaps(group);
  group.traverse((o) => { if (o.isMesh) { o.castShadow = o.receiveShadow = false; o.matrixAutoUpdate = false; o.updateMatrix(); } });

  // --- colliders: the json's boxes, and one per door leaf (from its hinge, along its closed direction, as the page builds them)
  const world = doc.colliders.map((c) => ({ n: c.min, x: c.max, s: c.s }));
  const doors = new Map();
  for (const d of doc.doors || []) {
    const th = d.closed_yaw_deg * Math.PI / 180, dir = [Math.cos(th), -Math.sin(th)];
    const [hx, hy, hz] = d.hinge, w = d.width, tx = Math.abs(dir[0]) < 0.5 ? 0.07 : 0, tz = Math.abs(dir[1]) < 0.5 ? 0.07 : 0;
    const box = { n: [Math.min(hx, hx + dir[0] * w) - tx, hy, Math.min(hz, hz + dir[1] * w) - tz], x: [Math.max(hx, hx + dir[0] * w) + tx, hy + (d.height || 2.1), Math.max(hz, hz + dir[1] * w) + tz], door: true, off: false, s: d.name };
    const leaf = group.getObjectByName(d.name) || null;
    const swing = (Math.abs(d.swing_deg || 95) * (d.swing_deg < 0 ? -1 : 1)) * Math.PI / 180;
    const dr = { d, box, leaf, p: 0, target: 0, qClosed: qy(th), qOpen: qy(th + swing) };
    if (leaf) { leaf.matrixAutoUpdate = true; leaf.quaternion.copy(dr.qClosed); }
    world.push(box);
    doors.set(d.name, dr);
  }
  const open = (name, now = false) => {
    const dr = doors.get(name);
    if (!dr) return;
    dr.target = 1;
    if (now) { dr.p = 1; dr.box.off = true; if (dr.leaf) dr.leaf.quaternion.copy(dr.qOpen); }
  };

  // --- the extent (the server's relay limits are checked against it) and the floor (for the fall catch)
  const ext = { minX: Infinity, maxX: -Infinity, minZ: Infinity, maxZ: -Infinity, minY: Infinity };
  for (const b of world) {
    ext.minX = Math.min(ext.minX, b.n[0]); ext.maxX = Math.max(ext.maxX, b.x[0]);
    ext.minZ = Math.min(ext.minZ, b.n[2]); ext.maxZ = Math.max(ext.maxZ, b.x[2]);
    ext.minY = Math.min(ext.minY, b.n[1]);
  }

  // --- where a walker coming in by `via` stands: that link's arrive and face; with no door, the room's Spawn (looking north) or its first way in
  const firstIn = Object.values(R.links).find((e) => e.to || e.arrival) || Object.values(R.links)[0];
  function arrival(via) {
    const e = via && R.links[via];
    if (e) {
      if (e.leaf && !e.arrival && e.kind !== 'one_way' && e.kind !== 'self') open(e.leaf, true);       // the door you came through stays open behind you (not a one-way one, nor a loop's)
      return { x: e.arrive[0], y: e.arrive[1], z: e.arrive[2], yaw: yawOf(e.face) };
    }
    if (R.spawn) return { x: R.spawn[0], y: R.spawn[1], z: R.spawn[2], yaw: 0 };
    return firstIn ? { x: firstIn.arrive[0], y: firstIn.arrive[1], z: firstIn.arrive[2], yaw: yawOf(firstIn.face) } : { x: 0, y: 0, z: 0, yaw: 0 };
  }

  // --- the ways out, as things to use. A link is in reach by the walker's feet (controls.feet(), read in update), not its eye
  let leaving = null, feet = 0;
  const links = [];
  for (const [door, e] of Object.entries(R.links)) {
    if (e.arrival) continue;                                      // an arrival door does not open back
    const shut = e.out === 'shut' || e.shut;
    links.push({
      x: e.at[0], y: e.at[1] + 1.2, z: e.at[2], reach: LINK_REACH, size: 0.6, aimless: true, door,
      label: shut ? 'IT DOES NOT OPEN' : labelOf(door, e),
      enabled: () => !leaving && Math.abs(feet - e.at[1]) < LINK_RISE,
      use(ctx) {
        if (shut) { ctx.sound.wrong(); return; }
        ctx.leaveBy(door);
      },
    });
  }
  const built = {};

  function leave(door, from) {
    const e = R.links[door];
    leaving = door;
    if (e.leaf) open(e.leaf);
    // walk to the link's mark and on through the door: outward is from where you land coming in toward where you leave
    const ox = e.at[0] - e.arrive[0], oz = e.at[2] - e.arrive[2], ol = Math.hypot(ox, oz) || 1;
    const eye = from.y - feet;
    const mark = new THREE.Vector3(e.at[0], e.at[1] + eye, e.at[2]);
    const beyond = new THREE.Vector3(e.at[0] + ox / ol * 1.3, e.at[1] + eye, e.at[2] + oz / ol * 1.3);
    built.exitPath = from.distanceTo(mark) < 0.2 ? [beyond] : [mark, beyond];
    built.exitLookAt = new THREE.Vector3(e.at[0] + ox / ol * 4, e.at[1] + eye, e.at[2] + oz / ol * 4);
  }

  // where leaving by `door` takes the walker; door null is the story's way on from this room (the test hook finish('reached') takes it too)
  function next(door) {
    const d = door === null || door === undefined ? SPINE[id] : door;
    if (d === null || d === undefined) return { leave: null };            // the end of the story: the game ends, as it did after the grocery
    const e = R.links[d];
    if (!e) return null;
    if (e.out === 'leave') return { leave: d };
    if (e.to) return { room: e.to.room, via: e.to.door };
    return null;
  }

  // --- the dining room's lamp clicks off every 28 s (its night bake is the room with the lamp off), as the code room's does
  const nightSet = bake.baked.some((m) => m.userData.sets.night);
  const lamp = id === 'dining' && nightSet ? { period: 28, offAt: 0.87, off: 3, on: true } : null;
  let lightSet = 'day';
  function setLightSet(name) {
    for (const m of bake.baked) { const [tex, k] = m.userData.sets[name] || m.userData.sets.day; if (m.lightMap !== tex) { m.lightMap = tex; m.lightMapIntensity = k; } }
    lightSet = name;
  }
  const glows = [];
  group.traverse((o) => { if (o.isMesh && o.material && /^Lamp_Emit/.test(o.material.name) && !glows.includes(o.material)) glows.push(o.material); });

  let elapsed = 0;
  function update(p, dt, camera, ctx) {
    if (dt === undefined) return;
    elapsed += dt;
    if (ctx.controls && !leaving) feet = ctx.controls.feet();
    for (const dr of doors.values()) {
      if (dr.p === dr.target) continue;
      dr.p = dr.target > dr.p ? Math.min(dr.target, dr.p + dt * 2.8) : Math.max(dr.target, dr.p - dt * 2.8);
      if (dr.leaf) { const k = dr.p * dr.p * (3 - 2 * dr.p); dr.leaf.quaternion.slerpQuaternions(dr.qClosed, dr.qOpen, k); }
      dr.box.off = dr.p > 0.5;
    }
    if (lamp) {
      const ph = (elapsed % lamp.period) / lamp.period;
      const on = !(ph > lamp.offAt && ph < lamp.offAt + lamp.off / lamp.period);
      if (on !== lamp.on) {
        lamp.on = on;
        ctx.sound.click();
        setLightSet(on ? 'day' : 'night');
        for (const m of glows) m.emissiveIntensity = on ? (m.userData.emit0 ?? 1) : 0;
      }
    }
  }

  function dispose() {
    for (const t of bake.textures) t.dispose();
  }

  const start = arrival(null);
  Object.assign(built, {
    meta: {
      id,
      objective: codeMeta ? codeMeta.objective : 'FIND A WAY OUT',
      arrive: codeMeta ? codeMeta.arrive : 'GO THROUGH',
      start,
      title: R.title,
    },
    blender: true, sceneId: R.scene, room: R,
    group, lights: new THREE.Group(), colliders: [], world, doors, interact: links, links, update, dispose,
    bounds: { minX: ext.minX, maxX: ext.maxX, minZ: ext.minZ, maxZ: ext.maxZ },
    floorY: ext.minY,
    arrival, leave, next,
    exitPath: [], exitLookAt: new THREE.Vector3(),
    exitDuration: 1.4, exitFadeStart: 0.35, exitTurn: 2.2,
    background: 0x000000,
    fog: null,
    far: 160,
    exposure: 1,
    toneMapping: THREE.NoToneMapping,
    environment: false,
    walkerScale: 1,
    debug: { bake, doors, get lightSet() { return lightSet; }, lamp, get leaving() { return leaving; }, get elapsed() { return elapsed; } },
  });
  return built;
}
